WITH with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC) AS prev_paid_at FROM payments), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessionized AS (SELECT id, method, paid_at, status, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, status, COUNT(DISTINCT id) AS distinct_ids, COUNT(CASE WHEN status = 'FAILED' THEN 1 END) AS failed_count FROM sessionized GROUP BY 1, 2;
